/* ============================================================ */
export default function LingjingApp() {
  const [screen, setScreen] = useState("landing"); // landing|map|intro|mission|play|finish|poster
  const [locId, setLocId] = useState(null);
  const [roleId, setRoleId] = useState(null); // 当前灵境所选角色
  const [qIndex, setQIndex] = useState(0);
  const [doneLocs, setDoneLocs] = useState({}); // id -> true
  const [stamps, setStamps] = useState([]);     // [{id,name,stamp,color}]
  const [reward, setReward] = useState(null);
  const [butlerOpen, setButlerOpen] = useState(false);

  const loc = LOCATIONS.find((l) => l.id === locId);
  const role = loc?.roles.find((r) => r.id === roleId) || null;

  const enterLoc = (id) => { setLocId(id); setRoleId(null); setQIndex(0); setScreen("intro"); };
  const finishLoc = () => {
    setDoneLocs((d) => ({ ...d, [locId]: true }));
    setStamps((s) => s.find((x) => x.id === locId) ? s : [...s, { id: loc.id, name: loc.name, stamp: loc.stamp, color: loc.color }]);
    setReward(loc);
  };
  const closeReward = () => { setReward(null); setScreen("finish"); };

  return (
    <div className="lj">
      <style>{CSS}</style>
      <div className="lj-aurora" />
      <div className="lj-grain" />

      <div className={"lj-shell " + (screen === "map" ? "wide" : "")}>
        <TopBar onLogo={() => setScreen("landing")} />

        {screen === "landing" && <Landing onEnter={() => setScreen("map")} />}
        {screen === "map" && (
          <MapScreen doneLocs={doneLocs} onEnter={enterLoc} />
        )}
        {screen === "intro" && loc && (
          <Intro loc={loc} roleId={roleId} onSelectRole={setRoleId}
            onNext={() => setScreen("mission")} onBack={() => setScreen("map")} />
        )}
        {screen === "mission" && loc && role && (
          <Mission loc={loc} role={role} onStart={() => { setQIndex(0); setScreen("play"); }} onBack={() => setScreen("intro")} />
        )}
        {screen === "play" && loc && (
          <Play
            loc={loc} qIndex={qIndex}
            onNext={() => {
              if (qIndex + 1 < loc.questions.length) setQIndex(qIndex + 1);
              else finishLoc();
            }}
            onBack={() => setScreen("mission")}
          />
        )}
        {screen === "finish" && loc && (
          <Finish loc={loc} role={role} stamps={stamps} total={LOCATIONS.length}
            onMap={() => setScreen("map")} onPoster={() => setScreen("poster")} />
        )}
        {screen === "poster" && (
          <Poster stamps={stamps} total={LOCATIONS.length} role={role} loc={loc} onBack={() => setScreen("finish")} />
        )}
      </div>

      {reward && <Reward loc={reward} onClose={closeReward} />}

      {screen !== "landing" && (
        <>
          <button className="lj-butler-fab" onClick={() => setButlerOpen(true)}>
            <Wand2 size={20} /> <span>衍灵</span>
          </button>
          {butlerOpen && <Butler loc={loc} role={role} screen={screen} onClose={() => setButlerOpen(false)} />}
        </>
      )}
    </div>
  );
}

/* ---------- 顶栏 ---------- */
function TopBar({ onLogo }) {
  return (
    <div className="lj-top">
      <button className="lj-brand" onClick={onLogo}>
        <span className="lj-brand-mark">灵</span>
        <span className="lj-brand-name">灵境剧衍</span>
      </button>
      <span className="lj-brand-en">LINGJING · IMMERSIVE</span>
    </div>
  );
}

/* ---------- 1. 启动 ---------- */
function Landing({ onEnter }) {
  return (
    <div className="lj-screen lj-landing">
      <div className="lj-rise" style={{ animationDelay: "40ms" }}>
        <span className="lj-kicker">沉浸式文旅剧本游</span>
      </div>
      <h1 className="lj-hero lj-rise" style={{ animationDelay: "120ms" }}>
        灵境<span className="lj-hero-glow">剧衍</span>
      </h1>
      <p className="lj-hero-sub lj-rise" style={{ animationDelay: "200ms" }}>
        踏入八处灵境，以一个角色、一段故事，<br />重走山河之间的隐秘剧情。
      </p>
      <div className="lj-chips lj-rise" style={{ animationDelay: "280ms" }}>
        {["地图寻境", "角色入戏", "答题解谜", "集印成卷"].map((c) => (
          <span className="lj-chip" key={c}>{c}</span>
        ))}
      </div>
      <button className="lj-cta lj-rise" style={{ animationDelay: "360ms" }} onClick={onEnter}>
        <Compass size={18} /> 进入灵境
      </button>
      <p className="lj-tiny lj-rise" style={{ animationDelay: "440ms" }}>扫码 / 链接进入 · 手机与电脑均可游玩</p>
    </div>
  );
}

/* ---------- 2. 地图选点(带定位) ---------- */
function MapScreen({ doneLocs, onEnter }) {
  const [sel, setSel] = useState(null);
  const [userPos, setUserPos] = useState(null); // {x,y}
  const [nearest, setNearest] = useState(null);  // {loc, km}
  const [locating, setLocating] = useState(false);
  const selLoc = LOCATIONS.find((l) => l.id === sel);

  const pinXY = (l) => ({ x: projX(l.lng) + (l.dx || 0), y: projY(l.lat) + (l.dy || 0) });

  const locate = () => {
    setLocating(true);
    const handle = (lat, lng, mock) => {
      const me = { lat, lng };
      let best = null;
      LOCATIONS.forEach((l) => {
        const km = haversine(me, l);
        if (!best || km < best.km) best = { loc: l, km };
      });
      setNearest(best);
      // 把"我"投影到地图(超出边界则贴边显示)
      let x = projX(lng), y = projY(lat);
      x = Math.max(40, Math.min(860, x)); y = Math.max(40, Math.min(620, y));
      setUserPos({ x, y, mock });
      setLocating(false);
    };
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (p) => handle(p.coords.latitude, p.coords.longitude, false),
        () => handle(31.23, 121.47, true), // 拒绝/失败 → 模拟(上海附近)
        { timeout: 6000 }
      );
    } else handle(31.23, 121.47, true);
  };

  return (
    <div className="lj-screen">
      <div className="lj-head">
        <span className="lj-kicker">第一步 · 择境而入</span>
        <h2 className="lj-title">选择你的灵境</h2>
      </div>

      <div className="lj-mapwrap">
        <svg viewBox="0 0 900 660" className="lj-map" preserveAspectRatio="xMidYMid meet">
          <defs>
            <radialGradient id="land" cx="42%" cy="38%">
              <stop offset="0%" stopColor="#1c2c52" />
              <stop offset="100%" stopColor="#0d1730" />
            </radialGradient>
            <filter id="cnglow" x="-25%" y="-25%" width="150%" height="150%">
              <feGaussianBlur stdDeviation="7" />
            </filter>
          </defs>
          {/* 经纬网格 */}
          {[...Array(11)].map((_, i) => (
            <line key={"h" + i} x1="30" y1={50 + i * 58} x2="870" y2={50 + i * 58} className="lj-grid" />
          ))}
          {[...Array(15)].map((_, i) => (
            <line key={"v" + i} x1={40 + i * 60} y1="30" x2={40 + i * 60} y2="630" className="lj-grid" />
          ))}
          {/* 中国版图(辉光 + 填充 + 省界) */}
          <path d={CHINA_MAP} fill="#3a78c8" opacity="0.22" filter="url(#cnglow)" />
          <path d={CHINA_MAP} fill="url(#land)" stroke="rgba(130,200,255,.4)" strokeWidth="0.8"
            strokeLinejoin="round" className="lj-land" />
          {/* 连境星线 */}
          {LOCATIONS.map((l, i) => {
            if (i === 0) return null;
            const a = pinXY(LOCATIONS[i - 1]), b = pinXY(l);
            return <line key={"k" + i} x1={a.x} y1={a.y} x2={b.x} y2={b.y} className="lj-link" />;
          })}
          {/* 用户定位 */}
          {userPos && (
            <g>
              <circle cx={userPos.x} cy={userPos.y} r="9" className="lj-me" />
              <circle cx={userPos.x} cy={userPos.y} r="9" className="lj-me-ping" />
              <text x={userPos.x} y={userPos.y - 16} className="lj-me-label">你在这里</text>
            </g>
          )}
          {/* 灵境点位 */}
          {LOCATIONS.map((l) => {
            const { x, y } = pinXY(l);
            const done = doneLocs[l.id], on = sel === l.id;
            return (
              <g key={l.id} className="lj-pin" onClick={() => setSel(l.id)} style={{ cursor: "pointer" }}>
                <circle cx={x} cy={y} r={on ? 16 : 11} fill={l.color}
                  style={{ filter: `drop-shadow(0 0 ${on ? 14 : 8}px ${l.color})`, transition: "all .2s" }} />
                <circle cx={x} cy={y} r="5" fill="#0a0e1a" />
                {done && <text x={x} y={y + 4} textAnchor="middle" fontSize="9" fill={l.color} fontWeight="700">✓</text>}
                <text x={x} y={y + 28} textAnchor="middle" className="lj-pin-label" fill={on ? l.color : "#cdd6f4"}>
                  {l.name}
                </text>
              </g>
            );
          })}
        </svg>

        <button className="lj-locate" onClick={locate} disabled={locating}>
          {locating ? <Loader2 size={16} className="lj-spin" /> : <Navigation size={16} />}
          {locating ? "定位中…" : "定位我的位置"}
        </button>
      </div>

      {nearest && (
        <div className="lj-toast">
          <MapPin size={14} /> 离你最近：<b style={{ color: nearest.loc.color }}>{nearest.loc.name}</b>
          <span className="lj-toast-km">约 {nearest.km} 公里</span>
          {userPos?.mock && <span className="lj-toast-mock">（定位模拟）</span>}
        </div>
      )}

      {selLoc && (
        <div className="lj-preview" style={{ borderColor: selLoc.color }}>
          <div className="lj-preview-top">
            <span className="lj-preview-nick" style={{ color: selLoc.color }}>{selLoc.nick}</span>
            <span className="lj-preview-name">{selLoc.name}</span>
          </div>
          <p className="lj-preview-story">{selLoc.story}</p>
          <div className="lj-preview-roles">
            <span className="lj-tiny">可选角色 {selLoc.roles.length} 种</span>
            <div className="lj-role-glyphs">
              {selLoc.roles.map((r) => (
                <span key={r.id} className="lj-role-glyph sm" style={{ borderColor: selLoc.color, color: selLoc.color }}>{r.glyph}</span>
              ))}
            </div>
          </div>
          <button className="lj-cta sm" style={{ background: selLoc.color, color: "#08101e" }}
            onClick={() => onEnter(selLoc.id)}>
            进入此灵境 <ChevronRight size={16} />
          </button>
        </div>
      )}
      {!selLoc && <p className="lj-tiny center" style={{ marginTop: 14 }}>点击地图上的光点，选择一处灵境</p>}
    </div>
  );
}

/* ---------- 3. 故事 + 角色选择(4-5个, 随景点自适应) ---------- */
function Intro({ loc, roleId, onSelectRole, onNext, onBack }) {
  return (
    <div className="lj-screen">
      <BackBtn onClick={onBack} />
      <div className="lj-head">
        <span className="lj-kicker" style={{ color: loc.color }}>{loc.nick}</span>
        <h2 className="lj-title">{loc.name}</h2>
      </div>
      <div className="lj-glass" style={{ borderColor: loc.color + "55" }}>
        <p className="lj-story">{loc.story}</p>
      </div>
      <p className="lj-tiny" style={{ letterSpacing: 3, margin: "18px 0 10px" }}>选择你的角色 · 入戏</p>
      <div className="lj-role-grid">
        {loc.roles.map((r, i) => {
          const on = roleId === r.id;
          return (
            <button key={r.id} className={"lj-role-opt lj-rise " + (on ? "on" : "")}
              style={{ animationDelay: `${i * 60}ms`, borderColor: on ? loc.color : undefined, boxShadow: on ? `0 0 18px ${loc.color}44` : undefined }}
              onClick={() => onSelectRole(r.id)}>
              <span className="lj-role-glyph" style={{ borderColor: loc.color, color: loc.color }}>{r.glyph}</span>
              <span className="lj-role-opt-meta">
                <b style={on ? { color: loc.color } : {}}>{r.name}</b>
                <em>{r.desc}</em>
              </span>
              {on && <Check size={16} style={{ color: loc.color, flex: "none" }} />}
            </button>
          );
        })}
      </div>
      <button className="lj-cta" style={{ background: loc.color, color: "#08101e", opacity: roleId ? 1 : .35, pointerEvents: roleId ? "auto" : "none" }} onClick={onNext}>
        以此身入境，领取任务 <ChevronRight size={18} />
      </button>
    </div>
  );
}

/* ---------- 4. 任务领取(灵境委托卷) ---------- */
function Mission({ loc, role, onStart, onBack }) {
  const n = loc.questions.length;
  const mins = 8 + n * 4;
  const [taken, setTaken] = useState(false);
  const accept = () => { setTaken(true); setTimeout(onStart, 620); };
  return (
    <div className="lj-screen">
      <BackBtn onClick={onBack} />
      <div className="lj-head">
        <span className="lj-kicker" style={{ color: loc.color }}>第二步 · 任务领取</span>
        <h2 className="lj-title">灵境委托</h2>
      </div>

      <div className="lj-quest" style={{ borderColor: loc.color + "55", borderLeftColor: loc.color }}>
        <span className={"lj-quest-seal " + (taken ? "taken" : "")} style={{ borderColor: loc.color, color: loc.color }}>
          {taken ? "领" : "令"}
        </span>
        <div className="lj-quest-from">
          <span className="lj-quest-avatar" style={{ background: loc.color }}><Wand2 size={12} /></span>
          委托人 · 衍灵　致 <b style={{ color: loc.color }}>{role.name}</b>
        </div>

        <p className="lj-qlabel">情境</p>
        <p className="lj-qstory">{loc.story}</p>

        <p className="lj-qlabel">你的使命</p>
        <p className="lj-qmission" style={{ color: loc.color }}>身为「{role.name}」，{role.desc}。</p>

        <p className="lj-qlabel">任务目标</p>
        <div className="lj-obj">
          <div className="lj-obj-item"><Target size={15} style={{ color: loc.color }} />解开 {n} 道与「{loc.name}」相关的谜题</div>
          <div className="lj-obj-item"><Stamp size={15} style={{ color: loc.color }} />全部答对，请回此境印章「{loc.stamp}」</div>
        </div>

        <div className="lj-taskmeta">
          <span className="lj-pill"><ScrollText size={12} /> 谜题 {n} 道</span>
          <span className="lj-pill"><Clock size={12} /> 约 {mins} 分钟</span>
          <span className="lj-pill"><Sparkles size={12} /> 随景点自适应</span>
          <span className="lj-pill"><Bot size={12} /> 可求助衍灵</span>
        </div>
      </div>

      <p className="lj-qlabel" style={{ margin: "18px 0 9px" }}>领取奖励</p>
      <div className="lj-rewards">
        <div className="lj-reward-chip" style={{ borderColor: loc.color + "55" }}>
          <span className="lj-reward-seal" style={{ borderColor: loc.color, color: loc.color }}>{loc.stamp}</span>
          <em>专属印章</em>
        </div>
        <div className="lj-reward-chip"><Award size={22} style={{ color: "#f0c674" }} /><em>{role.name}称号</em></div>
        <div className="lj-reward-chip"><Share2 size={22} style={{ color: "#3df0d8" }} /><em>游记海报 +1 印</em></div>
      </div>

      <button className="lj-cta" style={{ background: loc.color, color: "#08101e", marginTop: 22, opacity: taken ? .7 : 1 }}
        disabled={taken} onClick={accept}>
        {taken ? <><Check size={18} /> 已领取，入境中…</> : <><ScrollText size={18} /> 领取任务 · 入境</>}
      </button>
      <p className="lj-tiny center" style={{ marginTop: 10 }}>领取后即进入解谜，遇阻可随时召唤衍灵</p>
    </div>
  );
}

/* ---------- 5. 答题 ---------- */
function Play({ loc, qIndex, onNext, onBack }) {
  const data = loc.questions[qIndex];
  const [picked, setPicked] = useState(null);
  const [hint, setHint] = useState(false);
  useEffect(() => { setPicked(null); setHint(false); }, [qIndex]);
  const right = picked === data.answer;
  const wrong = picked !== null && !right;

  return (
    <div className="lj-screen">
      <BackBtn onClick={onBack} />
      <div className="lj-head">
        <span className="lj-kicker" style={{ color: loc.color }}>{loc.name} · 谜题 {qIndex + 1}/{loc.questions.length}</span>
        <div className="lj-prog"><div className="lj-prog-fill" style={{ width: `${(qIndex / loc.questions.length) * 100}%`, background: loc.color }} /></div>
      </div>
      <h3 className="lj-q">{data.q}</h3>
      <div className="lj-opts">
        {data.options.map((o, i) => {
          let cls = "lj-opt";
          if (picked === i) cls += right ? " ok" : " bad";
          const st = picked === i && right ? { borderColor: loc.color, boxShadow: `0 0 18px ${loc.color}55` } : {};
          return (
            <button key={i} className={cls} style={st} disabled={right} onClick={() => setPicked(i)}>
              <span className="lj-opt-k">{"ABCD"[i]}</span>{o}
              {picked === i && right && <Check size={16} style={{ marginLeft: "auto", color: loc.color }} />}
            </button>
          );
        })}
      </div>
      {wrong && <p className="lj-fb bad">差之毫厘，再想想～ {!hint && <button className="lj-link" onClick={() => setHint(true)}>请衍灵提示</button>}
        {hint && <span style={{ display: "block", marginTop: 6 }}>{data.hint}</span>}</p>}
      {right && <p className="lj-fb ok" style={{ color: loc.color }}>正解！谜题应声而解。</p>}
      <button className="lj-cta" style={{ background: loc.color, color: "#08101e", opacity: right ? 1 : .35, pointerEvents: right ? "auto" : "none" }} onClick={onNext}>
        {qIndex + 1 < loc.questions.length ? "下一题" : "完成 · 盖印"} <ChevronRight size={18} />
      </button>
    </div>
  );
}

/* ---------- 盖章反馈 ---------- */
function Reward({ loc, onClose }) {
  return (
    <div className="lj-mask" onClick={onClose}>
      <div className="lj-reward" onClick={(e) => e.stopPropagation()}>
        <span className="lj-tiny" style={{ letterSpacing: 4 }}>灵境印章 · 已得</span>
        <div className="lj-seal" style={{ borderColor: loc.color, color: loc.color, boxShadow: `0 0 40px ${loc.color}66, inset 0 0 0 4px #0a0e1a, inset 0 0 0 5px ${loc.color}` }}>
          {loc.stamp}
        </div>
        <p className="lj-muted">「{loc.name}」之印已收入灵境卷</p>
        <button className="lj-cta sm" style={{ background: loc.color, color: "#08101e", marginTop: 16 }} onClick={onClose}>继续</button>
      </div>
    </div>
  );
}

/* ---------- 6. 完成 ---------- */
function Finish({ loc, role, stamps, total, onMap, onPoster }) {
  const all = stamps.length >= total;
  return (
    <div className="lj-screen lj-center">
      <div className="lj-rise"><Award size={40} style={{ color: loc.color }} /></div>
      <h2 className="lj-title lj-rise" style={{ animationDelay: "80ms" }}>{loc.name} · 通关</h2>
      <p className="lj-muted lj-rise" style={{ animationDelay: "150ms" }}>
        授予称号 <b style={{ color: loc.color }}>{role.name}·{loc.stamp}印持有者</b>
      </p>
      <div className="lj-book lj-rise" style={{ animationDelay: "220ms" }}>
        {LOCATIONS.map((l) => {
          const got = stamps.find((s) => s.id === l.id);
          return <span key={l.id} className={"lj-book-seal " + (got ? "got" : "")}
            style={got ? { borderColor: l.color, color: l.color } : {}}>{got ? l.stamp : "·"}</span>;
        })}
      </div>
      <p className="lj-tiny lj-rise" style={{ animationDelay: "270ms" }}>灵境卷 · 已集 {stamps.length}/{total} 印</p>
      <div className="lj-actions lj-rise" style={{ animationDelay: "340ms" }}>
        {!all && <button className="lj-cta ghost" onClick={onMap}><Compass size={17} /> 再探其他灵境</button>}
        <button className="lj-cta" style={{ background: loc.color, color: "#08101e" }} onClick={onPoster}>
          <Share2 size={17} /> 生成游记海报
        </button>
      </div>
    </div>
  );
}

/* ---------- Canvas 辅助 ---------- */
const loadImg = (src) => new Promise((res, rej) => {
  const im = new Image(); im.onload = () => res(im); im.onerror = rej; im.src = src;
});
const rr = (ctx, x, y, w, h, r) => {
  ctx.beginPath(); ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r); ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r); ctx.arcTo(x, y, x + w, y, r); ctx.closePath();
};
const drawCover = (ctx, img, x, y, w, h) => {
  const ir = img.width / img.height, fr = w / h; let sw, sh, sx, sy;
  if (ir > fr) { sh = img.height; sw = sh * fr; sx = (img.width - sw) / 2; sy = 0; }
  else { sw = img.width; sh = sw / fr; sx = 0; sy = (img.height - sh) / 2; }
  ctx.drawImage(img, sx, sy, sw, sh, x, y, w, h);
};
const wrapText = (ctx, text, maxW, maxLines) => {
  const out = []; let line = "";
  for (const ch of text) {
    if (ch === "\n") { out.push(line); line = ""; continue; }
    if (ctx.measureText(line + ch).width > maxW && line) { out.push(line); line = ch; }
    else line += ch;
  }
  if (line) out.push(line);
  if (out.length > maxLines) { const t = out.slice(0, maxLines); t[maxLines - 1] = t[maxLines - 1].slice(0, -1) + "…"; return t; }
  return out;
};

/* ---------- 分享海报(可上传照片 + 可编辑旅行日记) ---------- */
function Poster({ stamps, total, role, loc, onBack }) {
  const ref = useRef(null);
  const fileRef = useRef(null);
  const [photo, setPhoto] = useState(null);   // dataURL
  const [diary, setDiary] = useState("");
  const [url, setUrl] = useState("");

  const onPick = (e) => {
    const f = e.target.files?.[0]; if (!f) return;
    const reader = new FileReader();
    reader.onload = () => setPhoto(reader.result); // dataURL 同源, 不污染画布
    reader.readAsDataURL(f);
  };

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const c = ref.current; if (!c) return;
      const dpr = 2, W = 360, H = 760; c.width = W * dpr; c.height = H * dpr;
      const ctx = c.getContext("2d"); ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      // 底色 + 极光
      const g = ctx.createLinearGradient(0, 0, W, H);
      g.addColorStop(0, "#0c1430"); g.addColorStop(.5, "#101a3a"); g.addColorStop(1, "#0a0e22");
      ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
      const ag = ctx.createLinearGradient(0, 0, W, 200);
      ag.addColorStop(0, "rgba(61,240,216,.25)"); ag.addColorStop(.5, "rgba(160,107,255,.22)"); ag.addColorStop(1, "rgba(255,94,160,.2)");
      ctx.fillStyle = ag; ctx.fillRect(0, 0, W, 210);
      ctx.strokeStyle = "rgba(240,198,116,.5)"; ctx.lineWidth = 1.5; ctx.strokeRect(16, 16, W - 32, H - 32);
      // 标题
      ctx.textAlign = "center";
      ctx.fillStyle = "#f4f4fb"; ctx.font = "bold 40px serif"; ctx.fillText("灵境剧衍", W / 2, 66);
      ctx.fillStyle = "#f0c674"; ctx.font = "12px serif"; ctx.fillText("— 灵境游记 · 纪念卷 —", W / 2, 90);
      if (role && loc) { ctx.fillStyle = "#9aa3c4"; ctx.font = "12px serif"; ctx.fillText(`${loc.name} · ${role.name}`, W / 2, 112); }
      // 照片框
      const px = 32, py = 128, pw = W - 64, ph = 176;
      ctx.save(); rr(ctx, px, py, pw, ph, 12); ctx.clip();
      if (photo) { try { const img = await loadImg(photo); if (cancelled) return; drawCover(ctx, img, px, py, pw, ph); } catch (e) { } }
      else {
        ctx.fillStyle = "rgba(120,160,255,.08)"; ctx.fillRect(px, py, pw, ph);
        ctx.fillStyle = "#6b76a8"; ctx.font = "13px serif"; ctx.fillText("＋ 上传你的旅行照片", W / 2, py + ph / 2 + 5);
      }
      ctx.restore();
      rr(ctx, px, py, pw, ph, 12); ctx.strokeStyle = (loc?.color || "#f0c674") + "99"; ctx.lineWidth = 1.5; ctx.stroke();
      // 旅行日记
      ctx.textAlign = "left";
      ctx.fillStyle = "#f0c674"; ctx.font = "13px serif"; ctx.fillText("旅行日记", px, 338);
      ctx.strokeStyle = "rgba(240,198,116,.3)"; ctx.beginPath(); ctx.moveTo(px + 64, 334); ctx.lineTo(W - px, 334); ctx.stroke();
      ctx.font = "13px serif";
      const txt = diary.trim() || "写下这趟旅程的心情……（在左侧编辑）";
      ctx.fillStyle = diary.trim() ? "#dfe4ff" : "#5a6498";
      wrapText(ctx, txt, pw, 6).forEach((ln, i) => ctx.fillText(ln, px, 362 + i * 23));
      // 印章
      ctx.textAlign = "center";
      ctx.fillStyle = "#cdd6f4"; ctx.font = "12px serif"; ctx.fillText(`灵境印 · 已集 ${stamps.length}/${total}`, W / 2, 522);
      const per = 5, gap = 60;
      (stamps.length ? stamps : []).forEach((s, i) => {
        const row = Math.floor(i / per), inRow = Math.min(stamps.length - row * per, per);
        const startX = W / 2 - ((inRow - 1) * gap) / 2;
        const x = startX + (i % per) * gap, y = 556 + row * 52;
        ctx.beginPath(); ctx.arc(x, y, 20, 0, Math.PI * 2);
        ctx.strokeStyle = s.color; ctx.lineWidth = 2; ctx.stroke();
        ctx.shadowColor = s.color; ctx.shadowBlur = 10;
        ctx.fillStyle = s.color; ctx.font = "bold 17px serif"; ctx.fillText(s.stamp, x, y + 6);
        ctx.shadowBlur = 0;
      });
      // 二维码 + 落款
      const qy = H - 96; ctx.fillStyle = "#f4f4fb"; ctx.fillRect(W / 2 - 28, qy, 56, 56);
      ctx.fillStyle = "#0c1430"; const n = 7, cell = 56 / n;
      for (let r = 0; r < n; r++) for (let col = 0; col < n; col++) if ((r * 5 + col * 3) % 2 === 0) ctx.fillRect(W / 2 - 28 + col * cell, qy + r * cell, cell, cell);
      ctx.fillStyle = "#9aa3c4"; ctx.font = "11px serif"; ctx.fillText("长按识别 · 一同入境", W / 2, qy + 74);
      if (!cancelled) {
        setUrl(c.toDataURL("image/png"));
        wechat.configShare({ title: "我在灵境剧衍集了印！", desc: diary.trim() || `已踏足 ${stamps.length}/${total} 处灵境`, link: location.href });
      }
    })();
    return () => { cancelled = true; };
  }, [photo, diary, stamps, total, role, loc]);

  return (
    <div className="lj-screen lj-center">
      <BackBtn onClick={onBack} />
      <div className="lj-head center"><span className="lj-kicker">游后产出 · 可编辑</span><h2 className="lj-title">灵境游记海报</h2></div>

      <div className="lj-editor">
        <input ref={fileRef} type="file" accept="image/*" onChange={onPick} style={{ display: "none" }} />
        <button className="lj-upload" onClick={() => fileRef.current?.click()}>
          <Download size={16} style={{ transform: "rotate(180deg)" }} /> {photo ? "更换照片" : "上传旅行照片"}
        </button>
        {photo && <button className="lj-rm" onClick={() => setPhoto(null)}>移除照片</button>}
        <textarea className="lj-diary" maxLength={120} value={diary}
          onChange={(e) => setDiary(e.target.value)}
          placeholder="写下这趟旅程的旅行日记…（最多 120 字，实时同步到海报）" />
        <span className="lj-tiny" style={{ alignSelf: "flex-end" }}>{diary.length}/120</span>
      </div>

      <canvas ref={ref} style={{ display: "none" }} />
      {url && <img src={url} alt="poster" className="lj-poster lj-rise" />}
      <p className="lj-tiny center" style={{ marginTop: 10 }}>微信内长按保存 · 浏览器可点下方下载</p>
      <a className="lj-cta" style={{ marginTop: 12, textDecoration: "none", maxWidth: 260 }} href={url} download="灵境剧衍-游记海报.png">
        <Download size={17} /> 保存海报
      </a>
    </div>
  );
}

/* ---------- AI 管家「衍灵」(本预览直连 Claude) ---------- */
function Butler({ loc, role, screen, onClose }) {
  const [msgs, setMsgs] = useState([
    { role: "assistant", content: "我是衍灵，灵境的引路人。山河有谜，尽可问我。" },
  ]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const bodyRef = useRef(null);
  useEffect(() => { bodyRef.current?.scrollTo(0, 1e6); }, [msgs, loading]);

  const ctx = loc ? `玩家此刻身处「${loc.name}」(${loc.nick})，角色是「${role?.name || "尚未选定"}」。` : "玩家正在地图上择境。";

  const send = async (text) => {
    const t = (text ?? input).trim(); if (!t || loading) return;
    const next = [...msgs, { role: "user", content: t }];
    setMsgs(next); setInput(""); setLoading(true);

    const system = `你是「灵境剧衍」沉浸式文旅剧本游戏的 AI 管家，名叫"衍灵"，是一位带几分仙气、温和睿智的引路人。${ctx} 职责：解说景点人文历史、给出剧情代入、在玩家求助时给"巧妙的提示"而非直接答案。风格：中文，语气古雅又亲切，每次回复不超过70字，可适度使用比喻。`;
    const messages = next.map((m) => ({ role: m.role, content: m.content }));

    // 未配置后端 → 演示模式(纯静态站默认走这里, 不报错)
    if (!BUTLER_API) {
      await new Promise((r) => setTimeout(r, 500));
      setMsgs((m) => [...m, { role: "assistant", content: "（演示模式）衍灵需接通后端方能开口。请在 src/LingjingApp.jsx 顶部设置 BUTLER_API，部署一个转发函数即可，详见 README。" }]);
      setLoading(false); return;
    }
    try {
      const res = await fetch(BUTLER_API, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ system, messages }),
      });
      const data = await res.json();
      const reply = Array.isArray(data.content)
        ? data.content.map((b) => (b.type === "text" ? b.text : "")).join("").trim()
        : (data.text || data.reply || "").trim();
      setMsgs((m) => [...m, { role: "assistant", content: reply || "（衍灵一时失语，请再问一次）" }]);
    } catch (e) {
      setMsgs((m) => [...m, { role: "assistant", content: "灵境信号微弱…稍后再试。" }]);
    } finally { setLoading(false); }
  };

  const quick = loc ? [`说说${loc.name}的来历`, "给我一点提示", "我该做什么？"] : ["这些灵境有何不同？", "推荐先去哪一处？"];

  return (
    <div className="lj-butler">
      <div className="lj-butler-head">
        <span className="lj-butler-avatar"><Bot size={18} /></span>
        <div><b>衍灵 · 灵境管家</b><em>AI 引路人</em></div>
        <button className="lj-x" onClick={onClose}><X size={18} /></button>
      </div>
      <div className="lj-butler-body" ref={bodyRef}>
        {msgs.map((m, i) => (
          <div key={i} className={"lj-bubble " + m.role}>{m.content}</div>
        ))}
        {loading && <div className="lj-bubble assistant"><Loader2 size={14} className="lj-spin" /> 衍灵思忖中…</div>}
      </div>
      <div className="lj-quick">
        {quick.map((q) => <button key={q} onClick={() => send(q)} disabled={loading}>{q}</button>)}
      </div>
      <div className="lj-butler-input">
        <input value={input} placeholder="向衍灵发问…" onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && send()} />
        <button onClick={() => send()} disabled={loading || !input.trim()}><Send size={16} /></button>
      </div>
    </div>
  );
}

